def digit_product_recursive(n: int) -> int:
    if n < 10:
        return n
    return (n % 10) * digit_product_recursive(n // 10)

def max_list_nesting_depth(data: list) -> int:
    return 1 + max(
        (max_list_nesting_depth(x) for x in data if isinstance(x, list)),
        default=0,
    )

def flatten_nested_tuples(t: tuple) -> list:
    result = []
    for item in t:
        if isinstance(item, tuple):
            result.extend(flatten_nested_tuples(item))
        else:
            result.append(item)
    return result

def reverse_string_recursive(s: str) -> str:
    if len(s) <= 1:
        return s
    mid = len(s) // 2
    return reverse_string_recursive(s[mid:]) + reverse_string_recursive(s[:mid])

def sum_nested_integers(data: list) -> int:
    total = 0
    for item in data:
        if isinstance(item, list):
            total += sum_nested_integers(item)
        elif isinstance(item, int) and not isinstance(item, bool):
            total += item
    return total

def is_alnum_palindrome_recursive(s: str) -> bool:
    def check(i: int, j: int) -> bool:
        if i >= j:
            return True
        if not s[i].isalnum():
            return check(i + 1, j)
        if not s[j].isalnum():
            return check(i, j - 1)
        if s[i].lower() != s[j].lower():
            return False
        return check(i + 1, j - 1)

    return check(0, len(s) - 1)

from functools import lru_cache


def count_monotone_grid_paths(rows: int, cols: int) -> int:
    if rows <= 0 or cols <= 0:
        return 0

    @lru_cache(maxsize=None)
    def paths(r: int, c: int) -> int:
        if r == 1 or c == 1:
            return 1
        return paths(r - 1, c) + paths(r, c - 1)

    return paths(rows, cols)

def binary_strings_without_adjacent_ones(n: int) -> list[str]:
    result = []

    def build(prefix: str) -> None:
        if len(prefix) == n:
            result.append(prefix)
            return
        build(prefix + '0')
        if not prefix or prefix[-1] != '1':
            build(prefix + '1')

    build('')
    return result

def collatz_steps_recursive(n: int) -> int:
    if n == 1:
        return 0
    nxt = n // 2 if n % 2 == 0 else 3 * n + 1
    return 1 + collatz_steps_recursive(nxt)

def count_nested_occurrences(data: list, target) -> int:
    count = 0
    for item in data:
        if isinstance(item, list):
            count += count_nested_occurrences(item, target)
        elif item == target:
            count += 1
    return count

def gcd_of_list_recursive(nums: list[int]) -> int:
    def gcd_pair(a: int, b: int) -> int:
        return a if b == 0 else gcd_pair(b, a % b)

    if not nums:
        return 0
    return gcd_pair(abs(nums[0]), gcd_of_list_recursive(nums[1:]))

def repeated_digit_sum(n: int) -> int:
    if n < 10:
        return n
    return repeated_digit_sum(sum(int(d) for d in str(n)))

def hanoi_move_list(n: int, source: str = 'A', target: str = 'C', spare: str = 'B') -> list[tuple[str, str]]:
    if n == 0:
        return []
    return (
        hanoi_move_list(n - 1, source, spare, target)
        + [(source, target)]
        + hanoi_move_list(n - 1, spare, target, source)
    )

def nested_dict_leaf_paths(d: dict) -> list[str]:
    paths = []

    def walk(node: dict, prefix: str) -> None:
        for key, value in node.items():
            path = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict) and value:
                walk(value, path)
            else:
                paths.append(path)

    walk(d, "")
    return paths

def replace_in_nested_list(data: list, old, new) -> list:
    return [
        replace_in_nested_list(item, old, new) if isinstance(item, list)
        else (new if item == old else item)
        for item in data
    ]

def count_k_subsets_with_sum(nums: list[int], k: int, target: int) -> int:
    n = len(nums)

    def count(i: int, need: int, remaining: int) -> int:
        if need == 0:
            return 1 if remaining == 0 else 0
        if n - i < need:
            return 0
        return count(i + 1, need - 1, remaining - nums[i]) + count(i + 1, need, remaining)

    return count(0, k, target)

def balanced_two_bracket_strings(n: int) -> list[str]:
    closer = {'(': ')', '[': ']'}
    result = []
    chars = []
    stack = []

    def backtrack(opens_left: int) -> None:
        if opens_left == 0 and not stack:
            result.append(''.join(chars))
            return
        if opens_left > 0:
            for opener in '([':
                chars.append(opener)
                stack.append(opener)
                backtrack(opens_left - 1)
                stack.pop()
                chars.pop()
        if stack:
            opener = stack.pop()
            chars.append(closer[opener])
            backtrack(opens_left)
            chars.pop()
            stack.append(opener)

    backtrack(n)
    return sorted(result)

def expand_brace_alternatives(pattern: str) -> list[str]:
    start = pattern.find('{')
    if start == -1:
        return [pattern]
    end = pattern.find('}', start)
    head = pattern[:start]
    options = pattern[start + 1:end].split(',')
    tails = expand_brace_alternatives(pattern[end + 1:])
    return sorted({head + option + tail for option in options for tail in tails})

