def count_palindromic_partitions(s: str) -> int:
    n = len(s)

    @lru_cache(maxsize=None)
    def ways(start: int) -> int:
        if start == n:
            return 1
        total = 0
        for end in range(start + 1, n + 1):
            piece = s[start:end]
            if piece == piece[::-1]:
                total += ways(end)
        return total

    return ways(0)

def letter_case_variants(s: str) -> list[str]:
    if not s:
        return ['']
    rest = letter_case_variants(s[1:])
    first = s[0]
    heads = {first.lower(), first.upper()} if first.isalpha() else {first}
    return sorted(head + tail for head in heads for tail in rest)

def grid_contains_word_path(grid: list[str], word: str) -> bool:
    if not word:
        return True
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    used = set()

    def search(r: int, c: int, i: int) -> bool:
        if grid[r][c] != word[i] or (r, c) in used:
            return False
        if i == len(word) - 1:
            return True
        used.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and search(nr, nc, i + 1):
                used.discard((r, c))
                return True
        used.discard((r, c))
        return False

    return any(search(r, c, 0) for r in range(rows) for c in range(cols))

def count_byte_value_splits(digits: str, parts: int) -> int:
    n = len(digits)

    def count(i: int, remaining: int) -> int:
        if remaining == 0:
            return 1 if i == n else 0
        total = 0
        for length in range(1, 4):
            if i + length > n:
                break
            piece = digits[i:i + length]
            if length > 1 and piece[0] == '0':
                break
            if int(piece) > 255:
                break
            total += count(i + length, remaining - 1)
        return total

    return count(0, parts)

def count_subsets_product_at_most(nums: list[int], limit: int) -> int:
    values = sorted(nums)

    def extend(start: int, product: int) -> int:
        count = 0
        for i in range(start, len(values)):
            new_product = product * values[i]
            if new_product > limit:
                break
            count += 1 + extend(i + 1, new_product)
        return count

    return extend(0, 1)

def reflected_gray_code(n: int) -> list[int]:
    if n == 0:
        return [0]
    previous = reflected_gray_code(n - 1)
    high_bit = 1 << (n - 1)
    return previous + [code | high_bit for code in reversed(previous)]

def region_sizes_descending(grid: list[str]) -> list[int]:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    seen = set()

    def fill(r: int, c: int) -> int:
        if not (0 <= r < rows and 0 <= c < cols):
            return 0
        if grid[r][c] != '#' or (r, c) in seen:
            return 0
        seen.add((r, c))
        return 1 + fill(r + 1, c) + fill(r - 1, c) + fill(r, c + 1) + fill(r, c - 1)

    sizes = [fill(r, c) for r in range(rows) for c in range(cols)
             if grid[r][c] == '#' and (r, c) not in seen]
    return sorted(sizes, reverse=True)

def plus_minus_expressions(digits: str, target: int) -> list[str]:
    n = len(digits)
    found = []

    def backtrack(i: int, expr: str, value: int) -> None:
        if i == n:
            if value == target:
                found.append(expr)
            return
        for j in range(i + 1, n + 1):
            piece = digits[i:j]
            if len(piece) > 1 and piece[0] == '0':
                break
            num = int(piece)
            if i == 0:
                backtrack(j, piece, num)
            else:
                backtrack(j, expr + '+' + piece, value + num)
                backtrack(j, expr + '-' + piece, value - num)

    if n:
        backtrack(0, '', 0)
    return sorted(found)

def count_rook_placements_avoiding(n: int, forbidden: set[tuple[int, int]]) -> int:
    used_cols = [False] * n

    def place(row: int) -> int:
        if row == n:
            return 1
        total = 0
        for col in range(n):
            if not used_cols[col] and (row, col) not in forbidden:
                used_cols[col] = True
                total += place(row + 1)
                used_cols[col] = False
        return total

    return place(0)

