def consecutive_number_split(s: str) -> list[int]:
    def follow(i: int, prev: int) -> Optional[list[int]]:
        if i == len(s):
            return []
        nxt = str(prev + 1)
        if not s.startswith(nxt, i):
            return None
        rest = follow(i + len(nxt), prev + 1)
        return None if rest is None else [prev + 1] + rest

    for length in range(1, len(s)):
        piece = s[:length]
        if length > 1 and piece[0] == '0':
            break
        first = int(piece)
        rest = follow(length, first)
        if rest is not None:
            return [first] + rest
    return []

def knight_squares_within_moves(n: int, start: tuple[int, int], k: int) -> int:
    jumps = ((1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1))
    best_remaining = {}

    def explore(r: int, c: int, remaining: int) -> None:
        if best_remaining.get((r, c), -1) >= remaining:
            return
        best_remaining[(r, c)] = remaining
        if remaining == 0:
            return
        for dr, dc in jumps:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                explore(nr, nc, remaining - 1)

    explore(start[0], start[1], k)
    return len(best_remaining)

def coin_partitions_listing(amount: int, coins: list[int]) -> list[tuple[int, ...]]:
    values = sorted(set(coins), reverse=True)
    result = []
    current = []

    def backtrack(remaining: int, first: int) -> None:
        if remaining == 0:
            result.append(tuple(current))
            return
        for i in range(first, len(values)):
            coin = values[i]
            if coin <= remaining:
                current.append(coin)
                backtrack(remaining - coin, i)
                current.pop()

    backtrack(amount, 0)
    return sorted(result)

