def all_word_break_sentences(s: str, words: list[str]) -> list[str]:
    vocabulary = set(words)
    lengths = sorted({len(w) for w in vocabulary if w})

    @lru_cache(maxsize=None)
    def segment(start: int) -> tuple[tuple[str, ...], ...]:
        if start == len(s):
            return ((),)
        results = []
        for length in lengths:
            word = s[start:start + length]
            if len(word) < length:
                break
            if word in vocabulary:
                for rest in segment(start + length):
                    results.append((word,) + rest)
        return tuple(results)

    return sorted(' '.join(parts) for parts in segment(0))

def count_domino_tilings(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    filled = [[ch == '#' for ch in row] for row in grid]

    def count(pos: int) -> int:
        while pos < rows * cols and filled[pos // cols][pos % cols]:
            pos += 1
        if pos == rows * cols:
            return 1
        r, c = divmod(pos, cols)
        total = 0
        filled[r][c] = True
        if c + 1 < cols and not filled[r][c + 1]:
            filled[r][c + 1] = True
            total += count(pos + 1)
            filled[r][c + 1] = False
        if r + 1 < rows and not filled[r + 1][c]:
            filled[r + 1][c] = True
            total += count(pos + 1)
            filled[r + 1][c] = False
        filled[r][c] = False
        return total

    return count(0)

def count_proper_colorings(n: int, edges: list[tuple[int, int]], k: int) -> int:
    earlier_neighbors = [set() for _ in range(n)]
    for u, v in edges:
        if u == v:
            return 0
        a, b = (u, v) if u < v else (v, u)
        earlier_neighbors[b].add(a)
    color = [-1] * n

    def assign(vertex: int) -> int:
        if vertex == n:
            return 1
        total = 0
        for c in range(k):
            if all(color[u] != c for u in earlier_neighbors[vertex]):
                color[vertex] = c
                total += assign(vertex + 1)
        color[vertex] = -1
        return total

    return assign(0)

def max_weight_simple_path(n: int, edges: list[tuple[int, int, int]]) -> int:
    adjacency = [[] for _ in range(n)]
    for u, v, w in edges:
        adjacency[u].append((v, w))
        adjacency[v].append((u, w))
    visited = [False] * n

    def extend(u: int) -> int:
        visited[u] = True
        best = 0
        for v, w in adjacency[u]:
            if not visited[v]:
                best = max(best, w + extend(v))
        visited[u] = False
        return best

    return max((extend(start) for start in range(n)), default=0)

import re
from functools import lru_cache


def all_parenthesization_values(expression: str) -> list[int]:
    tokens = re.findall(r'[0-9]+|[-+*]', expression)
    numbers = [int(t) for t in tokens[0::2]]
    operators = tokens[1::2]
    apply = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
    }

    @lru_cache(maxsize=None)
    def values(lo: int, hi: int) -> frozenset:
        if lo == hi:
            return frozenset([numbers[lo]])
        out = set()
        for split in range(lo, hi):
            op = apply[operators[split]]
            for a in values(lo, split):
                for b in values(split + 1, hi):
                    out.add(op(a, b))
        return frozenset(out)

    return sorted(values(0, len(numbers) - 1))

