def count_hamiltonian_paths(n: int, edges: list[tuple[int, int]]) -> int:
    if n == 0:
        return 0
    neighbors = [set() for _ in range(n)]
    for u, v in edges:
        if u != v:
            neighbors[u].add(v)
            neighbors[v].add(u)
    full = (1 << n) - 1

    @lru_cache(maxsize=None)
    def paths_from(last: int, visited: int) -> int:
        if visited == full:
            return 1
        return sum(
            paths_from(v, visited | (1 << v))
            for v in neighbors[last]
            if not visited & (1 << v)
        )

    return sum(paths_from(start, 1 << start) for start in range(n))

def can_split_into_equal_sum_groups(nums: list[int], k: int) -> bool:
    if len(nums) < k or not nums:
        return False
    total = sum(nums)
    if total % k:
        return False
    target = total // k
    values = sorted(nums, reverse=True)
    if values[0] > target:
        return False
    sums = [0] * k

    def place(i: int) -> bool:
        if i == len(values):
            return True
        tried = set()
        for g in range(k):
            if sums[g] in tried or sums[g] + values[i] > target:
                continue
            tried.add(sums[g])
            sums[g] += values[i]
            if place(i + 1):
                return True
            sums[g] -= values[i]
        return False

    return place(0)
